#include <iostream>
#include <string>
using namespace std;

bool fits(const string& s, const string& limit) {
    return s.size() < limit.size() ||
           (s.size() == limit.size() && s <= limit);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    while (cin >> s) {
        if (s.find_first_not_of("0123456789") != string::npos) {
            cout << "BigInteger\n";
            continue;
        }

        size_t pos = s.find_first_not_of('0');
        s = (pos == string::npos) ? "0" : s.substr(pos);

        if (fits(s, "127"))
            cout << "byte\n";
        else if (fits(s, "32767"))
            cout << "short\n";
        else if (fits(s, "2147483647"))
            cout << "int\n";
        else if (fits(s, "9223372036854775807"))
            cout << "long\n";
        else
            cout << "BigInteger\n";
    }

    return 0;
}

